insert into public.tenant_settings (tenant_id, business_name, tagline, description, logo_url, logo_shape, accent, theme_default, card_style, radius, font_display, font_body, font_cards, discounts_enabled, whatsapp, whatsapp_display, support_hours, location, currency_symbol, delivery_time, warranty_days, how_to_buy, terms, wa_order_template) values ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'C-Stream', 'Tu entretenimiento, sin complicaciones', 'Catálogo oficial de servicios digitales premium. Streaming, música, herramientas y más — al mejor precio, con garantía y soporte real.', '/demo/cstream/logo.webp', 'squircle', '#FF6B35', 'light', 'tecla', 18, 'bricolage', 'plus-jakarta', 'plus-jakarta', false, '51904670421', '+51 904 670 421', '24 horas, 7 días a la semana', 'Perú', 'S/', '5 a 15 minutos', 30, '[{"title": "Explora el catálogo", "text": "Busca, filtra por categoría y elige el tipo de acceso que necesitas."}, {"title": "Agrega al carrito", "text": "Suma todas las que quieras y revisa tu pedido antes de pagar."}, {"title": "Realiza el pago", "text": "YAPE, PLIN, LEMON, BCP o Binance. Los QR están en el checkout."}, {"title": "Recibe tu acceso", "text": "Te enviamos tus datos por WhatsApp en 5 a 15 minutos."}]'::jsonb, '[{"title": "Garantía de 30 días", "items": ["Todos nuestros servicios incluyen garantía de 30 días desde la activación.", "Cubre: Pérdida de acceso sin causa del cliente", "Cubre: Cuenta caída o bloqueada por el proveedor", "Cubre: Perfil eliminado sin intervención del cliente", "Cubre: Problemas de activación desde el inicio"]}, {"title": "La garantía no cubre", "items": ["Cambio de contraseña realizado por el cliente", "Compartir credenciales con terceros no autorizados", "Uso en más dispositivos de los permitidos", "Cierre de sesión forzado por mal uso", "Modificaciones a la configuración de la cuenta"]}, {"title": "Cómo reclamar", "items": ["Contactar por WhatsApp con captura de pantalla del problema. Respondemos en minutos.", "Reposición del servicio — no se realizan devoluciones de dinero"]}, {"title": "Reglas para acceso por perfil", "items": ["Usar en 1 dispositivo activo a la vez", "No cambiar el nombre del perfil asignado", "No modificar la configuración de la cuenta principal", "No cerrar sesión de otros dispositivos", "No intentar acceder a la configuración de la cuenta"]}, {"title": "Reglas para cuenta completa", "items": ["No cambiar el correo electrónico de la cuenta", "No activar verificación en dos pasos", "No vincular métodos de pago propios", "No cambiar la contraseña sin coordinación previa", "No compartir las credenciales con terceros"]}, {"title": "Entregas", "items": ["Normal: 5 a 15 minutos", "Hora punta (8:00 PM — 11:00 PM): 15 a 30 minutos", "En horario de alta demanda puede haber una pequeña espera. Siempre avisamos si hay demora."]}, {"title": "Devoluciones", "items": ["No se realizan devoluciones de dinero.", "En caso de problema cubierto por garantía, se repone el servicio sin costo adicional."]}]'::jsonb, 'Hola, {saludo} 👋 Soy {nombre}.
