  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'plin', 'PLIN', '970765248', 'Número', 'Carlos Ismael Estrada Manchay', '/demo/cstream/qr_plin.webp', '/library/pay/plin.webp', null, array['Abre tu app bancaria con PLIN (BBVA, Scotiabank, Interbank, BanBif)','Escanea el QR o ingresa el número','Ingresa el monto exacto de tu pedido','Toma captura del comprobante','Envíala por WhatsApp junto con tu pedido']::text[], 20, true),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'bcp', 'BCP', null, 'Número', 'Carlos Ismael Estrada Manchay', null, '/library/pay/bcp.webp', 'Solicitar número de cuenta por WhatsApp', array['Contáctanos por WhatsApp para obtener el número de cuenta BCP','Realiza la transferencia por la app BCP o Yape BCP','Ingresa el monto exacto de tu pedido','Toma captura del comprobante','Envíala por WhatsApp junto con tu pedido']::text[], 30, true),
