  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'binance', 'Binance Pay', '1155145233', 'ID Binance', 'Carlos Ismael Estrada Manchay', '/demo/cstream/qr_binance.webp', '/library/pay/binance.webp', 'El pago se realiza en USDT. El tipo de cambio se coordina por WhatsApp.', array['Abre tu app de Binance','Ve a Pay y selecciona ''Enviar''','Escanea el QR o ingresa el ID de Binance','Ingresa el monto exacto en USDT equivalente','Toma captura del comprobante','Envíala por WhatsApp junto con tu pedido']::text[], 50, true);
insert into public.faqs (tenant_id, question, answer, sort) values
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Qué es un acceso por perfil?', 'Un perfil es un acceso individual dentro de una cuenta compartida. Funciona en 1 dispositivo. Es la opción más económica y perfecta para uso personal.', 10),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Qué es una cuenta completa?', 'Incluye el correo y la contraseña de acceso. Tienes control total: ingresa desde cualquier dispositivo y gestiona la cuenta. Ideal si necesitas más flexibilidad.', 20),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Cuánto tarda la entrega?', 'Entre 5 y 15 minutos tras confirmar tu pago. Atendemos todos los días del año. En hora de alta demanda puede tomar un poco más, pero siempre avisamos.', 30),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Qué cubre la garantía de 30 días?', 'Pérdida de acceso sin causa del cliente, cuenta caída o perfil eliminado. No cubre cambios realizados por el cliente, como cambiar la contraseña o compartir las credenciales.', 40),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Cómo pago?', 'Aceptamos YAPE, BCP, PLIN, LEMON y Binance. En el checkout verás el QR y los datos de cada método. Realizas el pago, adjuntas el comprobante en WhatsApp y procesamos tu pedido.', 50),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿Puedo combinar varias plataformas?', 'Sí. Agrega todas las que quieras al carrito y paga en un solo pedido. Además, en la sección Combos tienes paquetes con precio especial.', 60),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', '¿YouTube Premium funciona diferente?', 'Sí. Necesitas un correo Gmail nuevo. Te enviamos una invitación al grupo familiar, válida 30 días. Puedes renovar con el mismo correo hasta 2 veces; del 3er mes en adelante se necesita un correo nuevo.', 70);
insert into public.announcements (tenant_id, title, message, image_url, tone, cta_label, cta_kind, cta_value, show_popup, sort) values
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'Combos con precio especial', 'Netflix + Spotify desde S/ 19.00 y más combinaciones con ahorro incluido. Agrégalos con un toque.', null, 'accent', 'Ver combos', 'url', '#combos', true, 10),
  ('1feabea1-88b3-5fb7-89c3-83eb2c6b89cb', 'Cineplanet con hasta 50% de descuento', 'Entradas y combos de dulcería. El precio depende de tu sede: escríbenos y te confirmamos antes de cobrar.', '/demo/cstream/cineplanet_combos.webp', 'info', 'Ver detalles', 'platform', '9795c3fd-a393-5c36-b975-c6cc0ab300ee', true, 20);
